theorem ordinalBlockMap_range (a : ℕ → Ordinal.{u}) (n : ℕ) :
    range (ordinalBlockMap a n) =
      {x | ordinalBlockStart a n ≤ x.val ∧ x.val ≤ ordinalBlockStart a n + a n}

